// Ein RSS-Feed liefert immer dieselben letzten Eintraege. Ohne Altersfilter
// wuerde der Workflow jeden Tag dieselben Artikel erneut vertexten — das kostet
// Tokens und produziert Dubletten im Freigabe-Sheet.
// 26 statt 24 Stunden als Puffer, falls der Lauf sich mal verspaetet.
const maxAlterStunden = 26;
const jetzt = Date.now();
const raus = [];

for (const eintrag of $input.all()) {
  const a = eintrag.json || {};
  const datum = a.isoDate || a.pubDate || a.date || null;
  const alterStunden = datum ? (jetzt - new Date(datum).getTime()) / 3600000 : 99999;
  if (alterStunden > maxAlterStunden || alterStunden < 0) continue;

  // HTML raus, Whitespace normalisieren — Roh-HTML im Prompt kostet nur Tokens.
  const roh = String(a['content:encoded'] || a.content || a.contentSnippet || '');
  const text = roh.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();

  // Aus einem Zweizeiler laesst sich kein sinnvoller Fachbeitrag ableiten.
  if (text.length < 200) continue;

  raus.push({
    json: {
      titel: a.title || 'Ohne Titel',
      link: a.link || '',
      veroeffentlicht: datum ? new Date(datum).toLocaleDateString('de-DE') : '',
      auszug: text.slice(0, 4000)
    }
  });
}

// Leeres Ergebnis wuerde den ganzen Strang stumm abbrechen. Ein Marker-Item
// haelt den Zweig sichtbar und macht Leerlaeufe im Execution-Log erkennbar.
if (raus.length === 0) return [{ json: { keine_neuen_artikel: true, geprueft_am: new Date().toLocaleDateString('de-DE') } }];
return raus;

// Beide KI-Ergebnisse zusammenfuehren und gegen die harten Plattformgrenzen
// pruefen. Ein Beitrag, der erst beim Einfuegen in LinkedIn abgeschnitten wird,
// faellt sonst erst der Marketing-Person auf — hier steht es vorab im Sheet.
const LIMIT_LINKEDIN = 3000;
const LIMIT_INSTAGRAM = 2200;
const raus = [];

for (const eintrag of $input.all()) {
  const bild = eintrag.json.message?.content ?? eintrag.json;
  const texte = $('Beitraege texten').item.json.message?.content ?? $('Beitraege texten').item.json;
  const artikel = $('Neue Artikel filtern').item.json;

  const liText = String(texte.linkedin_text || '');
  const igText = String(texte.instagram_text || '');
  const liTags = Array.isArray(texte.linkedin_hashtags) ? texte.linkedin_hashtags : [];
  const igTags = Array.isArray(texte.instagram_hashtags) ? texte.instagram_hashtags : [];

  const maengel = [];
  if (liText.length === 0) maengel.push('LinkedIn-Text fehlt');
  if (liText.length > LIMIT_LINKEDIN) maengel.push('LinkedIn-Text ueberschreitet ' + LIMIT_LINKEDIN + ' Zeichen');
  if (igText.length === 0) maengel.push('Instagram-Text fehlt');
  if (igText.length > LIMIT_INSTAGRAM) maengel.push('Instagram-Text ueberschreitet ' + LIMIT_INSTAGRAM + ' Zeichen');
  if (liTags.length < 3) maengel.push('Zu wenige LinkedIn-Hashtags');
  if (igTags.length < 6) maengel.push('Zu wenige Instagram-Hashtags');
  if (texte.hinweis) maengel.push('KI-Anmerkung: ' + texte.hinweis);
  if (bild.eignung === 'besser_eigenes_foto') maengel.push('KI empfiehlt ein echtes Foto statt eines generierten Bildes');

  raus.push({
    json: {
      erfasst_am: new Date().toLocaleDateString('de-DE'),
      titel: artikel.titel,
      link: artikel.link,
      linkedin_text: liText,
      linkedin_hashtags: liTags.join(' '),
      linkedin_zeichen: liText.length,
      instagram_text: igText,
      instagram_hashtags: igTags.join(' '),
      instagram_zeichen: igText.length,
      bild_prompt: bild.bild_prompt || '',
      bild_alt_text: bild.bild_alt_text || '',
      bildstil: bild.bildstil || '',
      status: maengel.length ? 'Entwurf - bitte pruefen' : 'Entwurf - freigabebereit',
      pruefhinweis: maengel.length ? maengel.join('; ') : 'Keine Auffaelligkeiten'
    }
  });
}
return raus;

